SELECT Country FROM singer WHERE Age > 40
INTERSECT
SELECT Country FROM singer WHERE Age < 30;

SELECT s.Name, s.Location
FROM stadium s
WHERE EXISTS (
    SELECT 1 FROM concert c WHERE c.Stadium_ID = s.Stadium_ID AND c.Year = '2014'
)
AND EXISTS (
    SELECT 1 FROM concert c WHERE c.Stadium_ID = s.Stadium_ID AND c.Year = '2015'
);

SELECT S.Fname
FROM Student S
WHERE EXISTS (
    SELECT 1 FROM Has_Pet HP JOIN Pets P ON HP.PetID = P.PetID
    WHERE HP.StuID = S.StuID AND P.PetType = 'cat'
)
AND EXISTS (
    SELECT 1 FROM Has_Pet HP JOIN Pets P ON HP.PetID = P.PetID
    WHERE HP.StuID = S.StuID AND P.PetType = 'dog'
);

SELECT DISTINCT a.Airline
FROM airlines a
WHERE EXISTS (
    SELECT 1 FROM flights f WHERE f.Airline = a.uid AND f.SourceAirport = 'CVO'
)
AND NOT EXISTS (
    SELECT 1 FROM flights f WHERE f.Airline = a.uid AND f.SourceAirport = 'APG'
);

SELECT Name, Location, District
FROM shop
ORDER BY Number_products DESC;

SELECT p.first_name, p.last_name
FROM players p
WHERE EXISTS (
    SELECT 1 FROM matches m1 WHERE m1.winner_id = p.player_id AND m1.year = 2013
)
AND EXISTS (
    SELECT 1 FROM matches m2 WHERE m2.winner_id = p.player_id AND m2.year = 2016
);

SELECT p.first_name, p.country_code
FROM players p
WHERE EXISTS (
    SELECT 1 FROM matches m1 WHERE m1.winner_id = p.player_id AND m1.tourney_name = 'WTA Championships'
)
AND EXISTS (
    SELECT 1 FROM matches m2 WHERE m2.winner_id = p.player_id AND m2.tourney_name = 'Australian Open'
);

SELECT semester_name
FROM Semesters
WHERE semester_id NOT IN (SELECT DISTINCT semester_id FROM Student_Enrolment);

SELECT id FROM TV_Channel
WHERE NOT EXISTS (
    SELECT 1 FROM Cartoon
    WHERE Cartoon.Channel = TV_Channel.id
    AND Cartoon.Directed_by = 'Ben Jones'
);

SELECT COUNT(*) FROM CONTESTANTS c
LEFT JOIN VOTES v ON c.contestant_number = v.contestant_number
WHERE v.contestant_number IS NULL;

SELECT c.Name
FROM country c
WHERE EXISTS (
    SELECT 1 FROM countrylanguage cl WHERE cl.CountryCode = c.Code AND cl.Language = 'English'
)
AND EXISTS (
    SELECT 1 FROM countrylanguage cl WHERE cl.CountryCode = c.Code AND cl.Language = 'French'
);

