SELECT Record_Company FROM orchestra WHERE Year_of_Founded < 2003
INTERSECT
SELECT Record_Company FROM orchestra WHERE Year_of_Founded > 2003;

SELECT AVG(h.grade)
FROM Highschooler h
JOIN (SELECT DISTINCT student_id FROM Friend) f ON h.ID = f.student_id;

SELECT MIN(grade)
FROM Highschooler
WHERE ID NOT IN (SELECT student_id FROM Friend);

